using System.Net.WebSockets; using System.Text.Json; using Microsoft.AspNetCore.Builder; using PresenterConsole.Contracts; using PresenterConsole.Sync;
namespace PresenterConsole.Desktop;
public sealed class AgentServer: IAsyncDisposable { readonly IPresentationAdapter ppt; readonly SyncEngine sync; readonly SynchronizationContext ui; readonly List<WebSocket> sockets=[]; WebApplication? app; public AgentServer(IPresentationAdapter p,SyncEngine s){ppt=p;sync=s;ui=SynchronizationContext.Current??new SynchronizationContext();sync.CommandAccepted+=(_,c)=>ui.Post(_=>{if(c.Type==CommandType.Next)ppt.Next();else if(c.Type==CommandType.Previous)ppt.Previous();else if(c.Type==CommandType.GotoSlide&&c.Slide is int n)ppt.GotoSlide(n);},null);ppt.StateChanged+=(_,_)=>Broadcast();} public async Task StartAsync(CancellationToken token){var b=WebApplication.CreateBuilder();b.WebHost.UseUrls("http://0.0.0.0:5217");app=b.Build();app.UseWebSockets();app.MapGet("/",()=>Results.Redirect("/index.html"));app.UseStaticFiles();app.Map("/ws",Handle);await app.StartAsync(token);} async Task Handle(HttpContext c){if(!c.WebSockets.IsWebSocketRequest){c.Response.StatusCode=400;return;}using var ws=await c.WebSockets.AcceptWebSocketAsync();lock(sockets)sockets.Add(ws);await Send(ws,new(MessageType.State,State()));var buf=new byte[8192];try{while(ws.State==WebSocketState.Open){var r=await ws.ReceiveAsync(buf,CancellationToken.None);if(r.MessageType==WebSocketMessageType.Close)break;var m=JsonSerializer.Deserialize<WireMessage>(buf.AsSpan(0,r.Count));if(m?.Command is{ } cmd){if(cmd.Type==CommandType.SyncRequest)await Send(ws,new(MessageType.State,State()));else sync.TryAccept(cmd);}}}finally{lock(sockets)sockets.Remove(ws);}} PresentationState State()=>new(ppt.CurrentShowPosition,ppt.SlideCount,ppt.CurrentNotes,true,0); async void Broadcast(){WebSocket[] ss;lock(sockets)ss=sockets.ToArray();foreach(var s in ss)if(s.State==WebSocketState.Open)await Send(s,new(MessageType.State,State()));} static Task Send(WebSocket s,WireMessage m)=>s.SendAsync(JsonSerializer.SerializeToUtf8Bytes(m),WebSocketMessageType.Text,true,CancellationToken.None); public async ValueTask DisposeAsync(){if(app is not null)await app.StopAsync();}}